#!/usr/bin/env python3
"""
Proof-of-Concept: Keystream Reuse via Counter Wraparound in SDCTR Mode

This script demonstrates the vulnerability described in RFC 4344 Section 6.1.
It simulates an SSH-like encryption scenario using SDCTR mode where the counter
wraps around after encrypting 2^L blocks, causing keystream reuse.

The attacker captures ciphertexts encrypted with the reused keystream and XORs
them to cancel out the keystream, revealing the XOR of the plaintexts.
"""

import struct
from Crypto.Cipher import AES
from Crypto.Util.number import long_to_bytes, bytes_to_long

# Constants
BLOCK_SIZE = 16  # AES block size in bytes
COUNTER_SIZE = 4  # Simulated 32-bit counter (L=32 for demonstration)
MAX_COUNTER = 2 ** (COUNTER_SIZE * 8)  # 2^32

# Vulnerable SDCTR encryption function
def sdctr_encrypt(key, plaintext, counter_start=0):
    """
    Encrypts plaintext using SDCTR mode with a vulnerable counter implementation.
    The counter wraps around after MAX_COUNTER blocks, causing keystream reuse.
    """
    ciphertext = b''
    counter = counter_start
    
    # Process plaintext in blocks
    for i in range(0, len(plaintext), BLOCK_SIZE):
        block = plaintext[i:i+BLOCK_SIZE]
        
        # Pad block if necessary
        if len(block) < BLOCK_SIZE:
            block = block + b'\x00' * (BLOCK_SIZE - len(block))
        
        # Generate keystream block
        counter_bytes = struct.pack('>I', counter % MAX_COUNTER)  # Vulnerable: counter wraps
        keystream_block = AES.new(key, AES.MODE_ECB).encrypt(counter_bytes)
        
        # XOR plaintext with keystream
        encrypted_block = bytes(a ^ b for a, b in zip(block, keystream_block))
        ciphertext += encrypted_block
        
        # Increment counter
        counter += 1
    
    return ciphertext

# Attacker's analysis function
def analyze_keystream_reuse(ciphertext1, ciphertext2):
    """
    XORs two ciphertexts to cancel out the keystream, revealing the XOR of plaintexts.
    """
    # Ensure both ciphertexts are the same length
    min_len = min(len(ciphertext1), len(ciphertext2))
    
    # XOR the ciphertexts
    xor_result = bytes(a ^ b for a, b in zip(ciphertext1[:min_len], ciphertext2[:min_len]))
    
    return xor_result

def main():
    # Setup
    key = b'0123456789abcdef'  # 16-byte key for AES-128
    
    # Simulate two plaintexts that will be encrypted with the same keystream due to counter wraparound
    plaintext1 = b'The quick brown fox jumps over the lazy dog. ' * 10
    plaintext2 = b'A quick brown fox jumps over the lazy dog. ' * 10
    
    # Encrypt first plaintext
    ciphertext1 = sdctr_encrypt(key, plaintext1)
    
    # Simulate counter wraparound by starting the second encryption at the wrap point
    # In a real scenario, this would happen after encrypting 2^L blocks
    ciphertext2 = sdctr_encrypt(key, plaintext2, counter_start=MAX_COUNTER)
    
    # Attacker captures both ciphertexts
    print("Ciphertext 1 (hex):", ciphertext1[:32].hex())
    print("Ciphertext 2 (hex):", ciphertext2[:32].hex())
    
    # Attacker XORs the ciphertexts to cancel out the keystream
    xor_result = analyze_keystream_reuse(ciphertext1, ciphertext2)
    
    # The result is the XOR of the two plaintexts
    print("\nXOR of ciphertexts (hex):", xor_result[:32].hex())
    
    # Demonstrate plaintext recovery with known plaintext
    known_plaintext = b'The quick brown fox jumps over the lazy dog. '
    recovered_plaintext = bytes(a ^ b for a, b in zip(xor_result[:len(known_plaintext)], known_plaintext))
    
    print("\nRecovered plaintext:", recovered_plaintext.decode('utf-8', errors='ignore'))
    print("Expected plaintext:", plaintext2[:len(known_plaintext)].decode('utf-8', errors='ignore'))
    
    # Verify recovery
    if recovered_plaintext == plaintext2[:len(known_plaintext)]:
        print("\n[+] SUCCESS: Plaintext recovered successfully!")
    else:
        print("\n[-] FAILURE: Plaintext recovery failed.")

if __name__ == "__main__":
    main()